import{_ as t,o as a,c as o,ao as d}from"./chunks/framework.CShGCFPt.js";const g=JSON.parse('{"title":"What triggers a rebuild","description":"","frontmatter":{},"headers":[],"relativePath":"guide/rebuilds.md","filePath":"guide/rebuilds.md","lastUpdated":null}'),r={name:"guide/rebuilds.md"};function i(s,e,l,c,n,u){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="What-triggers-a-rebuild" tabindex="-1">What triggers a rebuild <a class="header-anchor" href="#What-triggers-a-rebuild" aria-label="Permalink to &quot;What triggers a rebuild {#What-triggers-a-rebuild}&quot;">​</a></h1><p>A target is rebuilt when, in order:</p><ol><li><p>you force it (<code>tar_make(force = true)</code>, <code>cue = :always</code>),</p></li><li><p>it has never been built, or its object or files are missing,</p></li><li><p>its last build failed,</p></li><li><p>the <strong>source of its function</strong> changed (comments, whitespace and moving code do not count),</p></li><li><p>the source of any <strong>user function, type or global it reaches</strong> changed (recursively, all methods),</p></li><li><p>its dependencies changed, or</p></li><li><p>an upstream value changed, or, for file and URL targets, a file&#39;s contents or a URL changed.</p></li></ol><p><code>tar_outdated()</code> reports the first reason that applies to each target.</p><p>A rebuilt target whose output is identical stops the change there: its consumers see an unchanged value and are not rebuilt (<em>early cutoff</em>).</p><h2 id="How-code-is-tracked" tabindex="-1">How code is tracked <a class="header-anchor" href="#How-code-is-tracked" aria-label="Permalink to &quot;How code is tracked {#How-code-is-tracked}&quot;">​</a></h2><p>Hashes come from parsed source, not lowered code, so upgrading Julia does not by itself rebuild anything.</p><ul><li><p>Methods that a macro or <code>struct</code> generates (<code>@kwdef</code> constructors, default constructors, <code>@eval</code>) are hashed from the macro call or <code>struct</code> that generates them, and user-defined macros are followed like functions.</p></li><li><p>Only code whose source cannot be found (defined with <code>eval</code>, or at the REPL without Revise) falls back to lowered code, and is flagged.</p></li><li><p>Hashes do not depend on the numbers Julia gives the functions it generates (keyword bodies such as <code>#f#12</code>, anonymous functions and closures). Generated functions, including lambdas stored in globals or captured by a target, are identified by what they do.</p></li><li><p>A name a function binds itself, such as an argument or a comprehension variable, is never mistaken for a global of the same name.</p></li></ul><p>&quot;User code&quot; is anything under the project directory, plus locations listed in <code>tar_pipeline(...; track = [MyLabUtils, &quot;../shared&quot;])</code> (or <code>@pipeline track = [...]</code>). Installed packages are covered by a Manifest check: when <code>Manifest.toml</code> changes, <code>tar_make</code> names the packages that moved, and <code>track_manifest = true</code> rebuilds everything.</p><p>Known limits: code reached only through dynamic dispatch on runtime values (<code>getfield(mod, sym)</code>), <code>@generated</code> functions, and several lambdas with identical arguments on one line (edits rebuild all of them). <code>cue = :always</code> and <code>tar_make(force = true)</code> cover these.</p><h2 id="Cues" tabindex="-1">Cues <a class="header-anchor" href="#Cues" aria-label="Permalink to &quot;Cues {#Cues}&quot;">​</a></h2><p>A target&#39;s <code>cue</code> changes which of these rules apply:</p><table tabindex="0"><thead><tr><th style="text-align:right;"><code>cue</code></th><th style="text-align:right;">Rebuilds</th></tr></thead><tbody><tr><td style="text-align:right;"><code>:thorough</code> (default)</td><td style="text-align:right;">by all the rules above</td></tr><tr><td style="text-align:right;"><code>:always</code></td><td style="text-align:right;">on every build</td></tr><tr><td style="text-align:right;"><code>:never</code></td><td style="text-align:right;">only when it is missing</td></tr><tr><td style="text-align:right;"><a href="/v0.1/api#Targets.Cue"><code>Cue</code></a><code>(code = false)</code></td><td style="text-align:right;">by all the rules except those turned off: <code>command</code> (its own code and seed), <code>code</code> (code it calls), <code>depend</code> (upstream changes) and <code>file</code> (its files or URLs)</td></tr><tr><td style="text-align:right;"><a href="/v0.1/api#Targets.cue_age"><code>cue_age</code></a><code>(Day(7))</code></td><td style="text-align:right;">also once its last build is older than the period, for scraped or remote data</td></tr><tr><td style="text-align:right;"><a href="/v0.1/api#Targets.cue_force"><code>cue_force</code></a><code>(condition)</code></td><td style="text-align:right;">also whenever <code>condition</code> is true when the pipeline is loaded</td></tr></tbody></table><p>For example, <code>cue = Cue(code = false)</code> keeps an expensive simulation from rebuilding after a refactor of the code it calls. Missing or failed targets are always rebuilt.</p><h2 id="Forgetting-results" tabindex="-1">Forgetting results <a class="header-anchor" href="#Forgetting-results" aria-label="Permalink to &quot;Forgetting results {#Forgetting-results}&quot;">​</a></h2><ul><li><p><a href="/v0.1/api#Targets.tar_invalidate"><code>tar_invalidate</code></a><code>(names = [:a])</code> forgets a target&#39;s metadata, so it rebuilds on the next run, but keeps its stored value, so <code>tar_read</code> still works.</p></li><li><p><a href="/v0.1/api#Targets.tar_delete"><code>tar_delete</code></a><code>(names = [:a])</code> deletes its value and metadata.</p></li><li><p><a href="/v0.1/api#Targets.tar_prune"><code>tar_prune</code></a><code>()</code> deletes stored targets that are no longer in the pipeline.</p></li><li><p><a href="/v0.1/api#Targets.tar_destroy"><code>tar_destroy</code></a><code>()</code> deletes the whole store, after asking.</p></li></ul>',16)])])}const p=t(r,[["render",i]]);export{g as __pageData,p as default};
